style.css:
@-moz-document domain("chat.openai.com") {
/* General text styling with monospace font */
    body, div, span, h1, h2, h3, p, button, input, textarea, a {
        font-family: "Courier New", Courier, monospace !important; /* Monospace font */
        color: #b39682 !important; /* Soft brown color for all text */
    }

    /* Background color */
    body, .sc-bdVaJa, .ChatContainer {
        background-color: #ffffff !important; /* White background */
    }

    /* Message bubbles */
    .message-in, .message-out {
        background-color: #f5e4d1 !important; /* Soft light brown bubbles */
        color: #b39682 !important; /* Brown text inside bubbles */
        border-radius: 12px !important; /* Rounded corners for message bubbles */
    }

    /* Buttons */
    .Button-sc-1bbyi96 {
        background-color: #b39682 !important; /* Soft brown buttons */
        color: #ffffff !important; /* White text on buttons */
        border-radius: 8px !important; /* Rounded corners for buttons */
    }

    /* Button hover effect */
    .Button-sc-1bbyi96:hover {
        background-color: #9c8067 !important; /* Darker brown on hover */
        border-radius: 8px !important;
    }

    /* Input box for typing */
    .Input-sc-1r8ojjc {
        background-color: #ffffff !important; /* White background for input */
        border: 1px solid #b39682 !important; /* Soft brown border */
        color: #b39682 !important; /* Brown text inside input */
        border-radius: 8px !important; /* Rounded corners for input */
    }

    /* Input box focus effect */
    .Input-sc-1r8ojjc:focus {
        border-color: #9c8067 !important; /* Darker brown border on focus */
    }

    /* Links */
    a {
        color: #b39682 !important; /* Brown links */
    }

    a:hover {
        color: #9c8067 !important; /* Darker brown on hover */
    }

    /* Sidebar (if applicable) */
    .sc-bdVaJa {
        background-color: #f5e4d1 !important; /* Light brown sidebar */
    }

    /* Scrollbar */
    ::-webkit-scrollbar {
        width: 8px !important;
    }

    ::-webkit-scrollbar-thumb {
        background-color: #b39682 !important; /* Soft brown scrollbar */
        border-radius: 10px !important; /* Rounded scrollbar thumb */
    }

    ::-webkit-scrollbar-thumb:hover {
        background-color: #9c8067 !important; /* Darker brown on hover */
    }

    /* Chat header (where user info is displayed) */
    .Header-sc-1j98x19 {
        background-color: #b39682 !important; /* Soft brown header */
        color: #ffffff !important; /* White text in header */
    }

    /* Active/clicked state: Rounded brown highlight */
    button:active, a:active {
        outline: 2px solid #b39682 !important; /* Brown outline for active state */
        outline-offset: -4px !important;
        border-radius: 12px !important; /* Rounded corners when clicked */
    }
}
